<template>
  <div class="register-screen"><div class="register-container"><header class="reg-header"><button class="back-btn" @click="$router.back()"><span class="material-symbols-outlined">arrow_forward</span></button><h1>إنشاء حساب</h1></header><img :src="logo" alt="العصر الذهبي" class="register-logo"/>
    <div class="steps"><span v-for="(label,index) in stepLabels" :key="label" :class="{active:step===index+1,done:step>index+1}"><b>{{ index+1 }}</b>{{ label }}</span></div>
    <section v-if="step===1" class="form-area"><h2>المعلومات الشخصية</h2><InputField v-model="form.fullName" icon="person" placeholder="الاسم الكامل"/><InputField v-model="form.phone" icon="phone" placeholder="رقم الهاتف" type="tel"/><InputField v-model="form.nationalId" icon="badge" placeholder="رقم البطاقة الوطنية" type="tel"/><button type="button" class="date-field" @click="showDateDialog=true"><span class="material-symbols-outlined">calendar_month</span><span class="date-value">{{ birthDateLabel }}</span><span class="material-symbols-outlined date-arrow">keyboard_arrow_left</span></button><InputField v-model="form.address" icon="location_on" placeholder="العنوان"/><div class="input-group"><span class="material-symbols-outlined input-icon">lock</span><input v-model="form.password" :type="showPass?'text':'password'" placeholder="كلمة المرور" class="input-field"/><button class="eye-btn" @click="showPass=!showPass"><span class="material-symbols-outlined">{{showPass?'visibility':'visibility_off'}}</span></button></div><button class="primary-btn" @click="nextStep">التالي</button></section>
    <section v-else-if="step===2" class="form-area"><h2>المعلومات الوظيفية</h2><div class="type-selector"><button :class="{active:form.type==='government'}" @click="form.type='government'"><span class="material-symbols-outlined">account_balance</span>موظف حكومي</button><button :class="{active:form.type==='private'}" @click="form.type='private'"><span class="material-symbols-outlined">business</span>قطاع خاص</button></div><template v-if="form.type==='government'"><div class="department-picker"><label><span class="material-symbols-outlined">domain</span><input v-model="departmentSearch" placeholder="ابحث عن اسم الدائرة" @focus="showDepartments=true"/><button v-if="form.department" @click="form.department='';departmentSearch=''">×</button></label><div v-if="showDepartments" class="department-list"><button v-for="department in filteredDepartments" :key="department" @click="chooseDepartment(department)">{{ department }}</button><p v-if="!filteredDepartments.length">لا توجد دائرة مطابقة</p></div></div><InputField v-model="form.jobTitle" icon="work" placeholder="المسمى الوظيفي"/></template><template v-else><InputField v-model="form.profession" icon="work" placeholder="المهنة"/><InputField v-model="form.workplace" icon="business" placeholder="جهة العمل"/><InputField v-model="form.activityName" icon="storefront" placeholder="اسم النشاط"/></template><button class="primary-btn" @click="nextStep">التالي</button><button class="back-step" @click="step=1">رجوع</button></section>
    <section v-else class="form-area"><h2>المستمسكات</h2><div class="photo-actions"><div class="profile-circle"><img v-if="profilePreview" :src="profilePreview"/><span v-else class="material-symbols-outlined">person</span></div><div><b>الصورة الشخصية</b><small>التقاط حي بالكاميرا أو رفع من الهاتف</small><div class="choice-row"><label><input class="file-input" type="file" accept="image/*" capture="user" @change="handleProfilePhoto"/><span class="material-symbols-outlined">photo_camera</span>التقاط صورة</label><label><input class="file-input" type="file" accept="image/*" @change="handleProfilePhoto"/><span class="material-symbols-outlined">upload</span>من الهاتف</label></div></div></div><DocumentCapture title="البطاقة الوطنية - الوجه الأمامي" icon="credit_card" :file="form.nationalFront" @change="file=>form.nationalFront=file"/><DocumentCapture title="البطاقة الوطنية - الوجه الخلفي" icon="credit_card" :file="form.nationalBack" @change="file=>form.nationalBack=file"/><DocumentCapture title="بطاقة السكن" icon="home" :file="form.residenceCard" @change="file=>form.residenceCard=file"/><DocumentCapture v-if="form.type==='government'" title="هوية الدائرة" icon="badge" :file="form.departmentId" @change="file=>form.departmentId=file"/><label class="consent"><input v-model="agreed" type="checkbox"/> <span>أوافق على شروط الاستخدام وسياسة الخصوصية</span></label><button class="primary-btn" :disabled="!agreed" @click="register">إنشاء الحساب</button><button class="back-step" @click="step=2">رجوع</button></section>
    <div class="login-link">لديك حساب بالفعل؟ <button @click="$router.push('/login')">تسجيل الدخول</button></div><div v-if="showDateDialog" class="calendar-overlay" @click.self="showDateDialog=false"><section class="calendar-dialog"><div class="calendar-tabs"><button :class="{active:calendarMode==='months'}" @click="calendarMode='months'">الشهر: {{ pickerMonth+1 }}</button><button :class="{active:calendarMode==='years'}" @click="calendarMode='years'">السنة: {{ pickerYear }}</button></div><template v-if="calendarMode==='days'"><div class="calendar-title"><button @click="changeMonth(-1)" aria-label="الشهر السابق"><span class="material-symbols-outlined">chevron_right</span></button><b>{{ String(pickerMonth+1).padStart(2,'0') }} / {{ pickerYear }}</b><button @click="changeMonth(1)" aria-label="الشهر التالي"><span class="material-symbols-outlined">chevron_left</span></button></div><div class="calendar-week"><span v-for="day in weekDays" :key="day">{{ day }}</span></div><div class="calendar-days"><i v-for="blank in firstDay" :key="`blank-${blank}`"></i><button v-for="day in daysInMonth" :key="day" :class="{selected:form.birthDate===dateValue(day)}" @click="selectBirthDate(day)">{{ day }}</button></div></template><div v-else-if="calendarMode==='months'" class="calendar-options month-options"><button v-for="month in 12" :key="month" :class="{selected:pickerMonth===month-1}" @click="pickerMonth=month-1;calendarMode='days'">{{ String(month).padStart(2,'0') }}</button></div><div v-else class="calendar-options year-options"><button v-for="year in yearOptions" :key="year" :class="{selected:pickerYear===year}" @click="pickerYear=year;calendarMode='days'">{{ year }}</button></div><button class="calendar-cancel" @click="showDateDialog=false">إلغاء</button></section></div>
  </div></div>
</template>
<script setup>
import { computed, defineComponent, h, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import logo from '../assets/logo-transparent-fast.png'
const router=useRouter(),step=ref(1),showPass=ref(false),profilePreview=ref(null),agreed=ref(false),departmentSearch=ref(''),showDepartments=ref(false),showDateDialog=ref(false),calendarMode=ref('days'),pickerMonth=ref(new Date().getMonth()),pickerYear=ref(new Date().getFullYear()-20)
const stepLabels=['المعلومات الشخصية','المعلومات الوظيفية','المستمسكات'];const departments=['وزارة التربية','وزارة الصحة','وزارة الداخلية','وزارة الدفاع','وزارة المالية','وزارة العدل','وزارة الكهرباء','وزارة النفط','أمانة بغداد','ديوان المحافظة'];const filteredDepartments=computed(()=>departments.filter(item=>item.includes(departmentSearch.value)));const yearOptions=Array.from({length:new Date().getFullYear()-1926+1},(_,index)=>new Date().getFullYear()-index);const weekDays=['ح','ن','ث','ر','خ','ج','س'];const daysInMonth=computed(()=>new Date(pickerYear.value,pickerMonth.value+1,0).getDate());const firstDay=computed(()=>new Date(pickerYear.value,pickerMonth.value,1).getDay());const birthDateLabel=computed(()=>{if(!form.birthDate)return 'تاريخ الميلاد';const [year,month,day]=form.birthDate.split('-');return `${day}/${month}/${year}`})
const form=reactive({fullName:'',phone:'',nationalId:'',birthDate:'',address:'',password:'',profilePhoto:null,type:'government',department:'',jobTitle:'',profession:'',workplace:'',activityName:'',nationalFront:null,nationalBack:null,residenceCard:null,departmentId:null})
const dateValue=day=>`${pickerYear.value}-${String(pickerMonth.value+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;const changeMonth=delta=>{pickerMonth.value+=delta;if(pickerMonth.value<0){pickerMonth.value=11;pickerYear.value--}if(pickerMonth.value>11){pickerMonth.value=0;pickerYear.value++}};const selectBirthDate=day=>{form.birthDate=dateValue(day);showDateDialog.value=false}
const InputField=defineComponent({props:['modelValue','icon','placeholder','type'],emits:['update:modelValue'],setup(props,{emit}){return()=>h('label',{class:'input-group'},[h('span',{class:'material-symbols-outlined input-icon'},props.icon),h('input',{class:'input-field',type:props.type||'text',placeholder:props.placeholder,required:true,value:props.modelValue,onInput:event=>emit('update:modelValue',event.target.value)})])}})
const DocumentCapture=defineComponent({props:['title','icon','file'],emits:['change'],setup(props,{emit}){const choose=event=>{const file=event.target.files?.[0];if(file)emit('change',file)};return()=>h('article',{class:['document-card',props.file&&'uploaded']},[h('span',{class:'material-symbols-outlined doc-icon'},props.file?'check_circle':props.icon),h('div',[h('b',props.title),h('small',props.file?'تمت إضافة الصورة':'الخيار الأساسي: التقاط صورة حية')]),h('div',{class:'choice-row'},[h('label',[h('input',{class:'file-input',type:'file',accept:'image/*',capture:'environment',onChange:choose}),h('span',{class:'material-symbols-outlined'},'photo_camera'),'التقاط']),h('label',[h('input',{class:'file-input',type:'file',accept:'image/*',onChange:choose}),h('span',{class:'material-symbols-outlined'},'upload'),'من الهاتف'])])])}})
const handleProfilePhoto=event=>{const file=event.target.files?.[0];if(file){form.profilePhoto=file;profilePreview.value=URL.createObjectURL(file)}}
const chooseDepartment=department=>{form.department=department;departmentSearch.value=department;showDepartments.value=false}
const nextStep=()=>{if(step.value===1&&(!form.fullName||!form.phone||!form.nationalId||!form.birthDate||!form.address||!form.password))return;if(step.value===2){const governmentMissing=form.type==='government'&&(!form.department||!form.jobTitle);const privateMissing=form.type==='private'&&(!form.profession||!form.workplace||!form.activityName);if(governmentMissing||privateMissing)return}step.value++}
const register=()=>{const requiredDocuments=[form.profilePhoto,form.nationalFront,form.nationalBack,form.residenceCard];if(!agreed.value||requiredDocuments.some(item=>!item))return;localStorage.setItem('golden_user',JSON.stringify({fullName:form.fullName,phone:form.phone,address:form.address,clientType:form.type,department:form.department}));localStorage.setItem('golden_guest','false');localStorage.setItem('golden_terms_pending','true');router.push('/home')}
</script>
<style>.photo-actions .choice-row label:nth-child(2){display:none}.photo-actions small{font-size:0}.photo-actions small::after{content:'التقاط حي بالكامرة';font-size:10px}</style>
<style>
